"""Trading calendar of all venues: the implementation of ``contracts.MarketCalendar``.

How it works
* Stock exchanges take their regular sessions (open, lunch break, close, holidays, early closes) from
  exchange_calendars, corrected by the override tables in ``venues.py``. Days without library data are
  built from weekdays + regular hours (minus the researched closures where known); that is logged once
  per venue as a warning.
* CRYPTO / KRAKEN / FX / CME are generated by rule and split at UTC midnight (their trading date is the UTC
  date). Every venue with rule 'always_open' (CRYPTO, KRAKEN) behaves identically: always open, one segment
  per UTC day.
* Per venue, all regular segments of a rolling window - about 6 years back to 400 days ahead of the
  first query, extended lazily when a query falls outside - are precomputed into immutable, sorted numpy
  arrays of epoch seconds. Every query is a binary search on them (``is_open``: a few microseconds).
* Thread-safe: a schedule is immutable and replaced as a whole; building is serialised per venue, and
  every call into exchange_calendars is serialised by one module lock.

Conventions
* Segments are half-open intervals [start, end); results are timezone-aware UTC datetimes.
* Naive datetimes raise ``ValueError``, unknown venue keys ``KeyError``.
* Contiguous segments (a 24h venue split at UTC midnight) form ONE phase in ``state()``: since, until,
  next_open and next_close refer to real openings and closings, never to the midnight split.
"""

import logging
import threading
import warnings
from collections.abc import Collection, Iterable, Sequence
from dataclasses import dataclass
from datetime import UTC, date, datetime, time, timedelta
from time import perf_counter
from typing import Final
from zoneinfo import ZoneInfo

import exchange_calendars as xcals
import numpy as np
import pandas as pd

from trading_local.markets.venues import (
    EXTRA_CLOSURES,
    FX_WEEK_CLOSE,
    FX_WEEK_OPEN,
    GLOBEX_DAILY_CLOSE,
    GLOBEX_DAILY_OPEN,
    RESEARCHED_CLOSURES,
    RULE_TIMEZONE,
    VENUES,
    ExtendedHours,
    Venue,
    VenueRule,
)
from trading_local.models import SessionSegment, SessionState

log = logging.getLogger(__name__)

HISTORY_DAYS: Final = 6 * 365 + 2  # rolling window: days before the first query ...
LOOKAHEAD_DAYS: Final = 400  # ... and after it

# Notes shown by the GUI (German).
NOTE_OPEN: Final = "Handel"
NOTE_EARLY_CLOSE: Final = "Handel (verkürzter Handelstag)"
NOTE_LUNCH: Final = "Mittagspause"
NOTE_PAUSE: Final = "Handelspause"  # daily CME Globex break
NOTE_PRE: Final = "Vorbörse"
NOTE_POST: Final = "Nachbörse"
NOTE_WEEKEND: Final = "Wochenende"
NOTE_HOLIDAY: Final = "Feiertag"
NOTE_CLOSED: Final = "Geschlossen"
NOTE_ALWAYS_OPEN: Final = "Rund um die Uhr"

_DAY: Final = 86_400
# Every query needs this much schedule on both sides of the queried instant to find the previous and the
# next segment. The longest closure of any venue is about 12 days (Taiwan, Lunar New Year 2027).
_MARGIN: Final = 30 * _DAY
_LIBRARY_MIN_SPAN_DAYS: Final = 14  # exchange_calendars rejects ranges without a session
_EPOCH: Final = datetime(1970, 1, 1, tzinfo=UTC)
_EPOCH_ORDINAL: Final = date(1970, 1, 1).toordinal()
_EPOCH_WEEKDAY: Final = 3  # 1970-01-01 was a Thursday (Monday = 0)
_SATURDAY: Final = 5
_SUNDAY: Final = 6
_THURSDAY: Final = 3
_SECOND: Final = timedelta(seconds=1)
_MICROSECOND: Final = timedelta(microseconds=1)
_MICROS: Final = 1_000_000
_NANOS: Final = 1_000_000_000
_NAT: Final = np.iinfo(np.int64).min  # NaT in exchange_calendars' *_nanos arrays
_NO_DAYS: Final = np.empty(0, dtype=np.int64)
_NAIVE_ERROR: Final = "naive datetime: all datetimes in this code base must be timezone-aware"

# Serialises all calls into exchange_calendars: its calendar cache is not thread-safe, and the warning
# filter of _library_segments (warnings.catch_warnings is process-global) must not interleave with another.
_LIBRARY_LOCK = threading.Lock()


# ------------------------------------------------------------------------------------------------
# Time helpers
# ------------------------------------------------------------------------------------------------
def _seconds(at: datetime) -> int:
    """Epoch seconds of an aware datetime, rounded down (exact when compared with whole-second boundaries)."""
    if at.tzinfo is None:
        raise ValueError(_NAIVE_ERROR)
    return (at - _EPOCH) // _SECOND


def _ceil_seconds(at: datetime) -> int:
    """Epoch seconds of an aware datetime, rounded up."""
    if at.tzinfo is None:
        raise ValueError(_NAIVE_ERROR)
    return -((_EPOCH - at) // _SECOND)


def _micros(at: datetime) -> int:
    """Exact epoch microseconds of an aware datetime."""
    if at.tzinfo is None:
        raise ValueError(_NAIVE_ERROR)
    return (at - _EPOCH) // _MICROSECOND


def _utc(ts: int | np.integer) -> datetime:
    return datetime.fromtimestamp(int(ts), UTC)


def _utc_at(values: np.ndarray, index: int) -> datetime | None:
    """``values[index]`` as UTC datetime; None outside the array (cannot happen inside the safety margin)."""
    return _utc(values[index]) if 0 <= index < len(values) else None


def _to_date(day: int | np.integer) -> date:
    """Calendar date of an epoch day (days since 1970-01-01)."""
    return date.fromordinal(_EPOCH_ORDINAL + int(day))


def _epoch_day(value: date) -> int:
    return value.toordinal() - _EPOCH_ORDINAL


def _weekday(day: int | np.ndarray) -> int | np.ndarray:
    """Weekday (Monday = 0) of epoch day(s)."""
    return (day + _EPOCH_WEEKDAY) % 7


def _local_ts(day: int, at: time, zone: ZoneInfo) -> int:
    """Epoch seconds of the local wall-clock time ``at`` on epoch day ``day`` in ``zone``."""
    return int(datetime.combine(_to_date(day), at, tzinfo=zone).timestamp())


def _epoch_days(index: pd.DatetimeIndex) -> np.ndarray:
    """Epoch days of tz-naive midnight timestamps (exchange_calendars session labels)."""
    return index.to_numpy().astype("datetime64[D]").astype(np.int64)


# ------------------------------------------------------------------------------------------------
# Schedule data
# ------------------------------------------------------------------------------------------------
@dataclass(frozen=True, slots=True)
class _Segments:
    """Regular segments before assembly: trading date (epoch day), start and end (epoch seconds)."""

    day: np.ndarray
    start: np.ndarray
    end: np.ndarray

    @classmethod
    def of(cls, rows: Sequence[tuple[int, int, int]]) -> _Segments:
        """From (day, start, end) rows."""
        table = np.asarray(rows, dtype=np.int64).reshape(-1, 3)
        return cls(table[:, 0], table[:, 1], table[:, 2])

    @classmethod
    def concat(cls, parts: Sequence[_Segments]) -> _Segments:
        if not parts:
            return cls.of([])
        return cls(
            np.concatenate([part.day for part in parts]),
            np.concatenate([part.start for part in parts]),
            np.concatenate([part.end for part in parts]),
        )

    def select(self, mask: np.ndarray) -> _Segments:
        return _Segments(self.day[mask], self.start[mask], self.end[mask])

    def without_days(self, days: Collection[date]) -> _Segments:
        if not days:
            return self
        return self.select(~np.isin(self.day, np.array([_epoch_day(day) for day in days], dtype=np.int64)))


@dataclass(frozen=True, slots=True, eq=False)
class _Schedule:
    """All regular segments of one venue for its trading dates ``first_day..last_day`` (epoch days).

    Immutable, sorted int64 arrays of epoch seconds. A *session* is one trading date with its segments;
    a *run* is a maximal chain of segments where each starts exactly at the end of the previous one.
    """

    first_day: int
    last_day: int
    seg_start: np.ndarray
    seg_end: np.ndarray
    seg_session: np.ndarray  # session index of each segment
    run_start: np.ndarray  # start / end of the run that contains the segment
    run_end: np.ndarray
    run_next: np.ndarray  # index of the first segment after that run
    cum_before: np.ndarray  # trading seconds of all earlier segments
    cum_end: np.ndarray  # cum_before + own duration
    session_day: np.ndarray  # trading date (epoch day) of each session, ascending
    session_first: np.ndarray  # index of its first and last segment
    session_last: np.ndarray
    session_end: np.ndarray  # end of its last segment, ascending
    session_early: np.ndarray  # bool: early close
    ext_start: np.ndarray  # pre-market / after-hours windows, ascending
    ext_end: np.ndarray
    ext_is_post: np.ndarray  # bool: True = after-hours, False = pre-market

    @classmethod
    def assemble(
        cls,
        segments: _Segments,
        early_days: np.ndarray,
        first_day: int,
        last_day: int,
        extended: ExtendedHours | None,
        zone: ZoneInfo,
    ) -> _Schedule:
        """Sort and index raw segments; derive sessions, runs and the extended-hours windows."""
        order = np.argsort(segments.start, kind="stable")
        day, start, end = segments.day[order], segments.start[order], segments.end[order]
        count = len(start)
        if count == 0 or np.any(end <= start) or np.any(start[1:] < end[:-1]) or np.any(day[1:] < day[:-1]):
            raise ValueError(f"invalid trading segments for days {_to_date(first_day)}..{_to_date(last_day)}")
        new_session = np.ones(count, dtype=bool)
        new_session[1:] = day[1:] != day[:-1]
        session_first = np.flatnonzero(new_session)
        session_last = np.append(session_first[1:] - 1, count - 1)
        new_run = np.ones(count, dtype=bool)
        new_run[1:] = start[1:] != end[:-1]
        run_id = np.cumsum(new_run) - 1
        run_first = np.flatnonzero(new_run)
        run_last = np.append(run_first[1:] - 1, count - 1)
        duration = end - start
        cum_end = np.cumsum(duration)
        session_day = day[session_first]
        session_early = np.isin(session_day, early_days)
        ext_start, ext_end, ext_is_post = _extended_windows(
            extended, zone, session_day, start[session_first], end[session_last], session_early
        )
        arrays = {
            "seg_start": start,
            "seg_end": end,
            "seg_session": np.cumsum(new_session) - 1,
            "run_start": start[run_first][run_id],
            "run_end": end[run_last][run_id],
            "run_next": (run_last + 1)[run_id],
            "cum_before": cum_end - duration,
            "cum_end": cum_end,
            "session_day": session_day,
            "session_first": session_first,
            "session_last": session_last,
            "session_end": end[session_last],
            "session_early": session_early,
            "ext_start": ext_start,
            "ext_end": ext_end,
            "ext_is_post": ext_is_post,
        }
        for array in arrays.values():
            array.flags.writeable = False
        return cls(first_day=first_day, last_day=last_day, **arrays)

    def covers(self, t_lo: int, t_hi: int) -> bool:
        """True if queries for every instant in [t_lo, t_hi] (epoch seconds) can be answered."""
        return self.first_day * _DAY + _MARGIN <= t_lo and t_hi <= (self.last_day + 1) * _DAY - _MARGIN

    def segment_index(self, t: int) -> int:
        """Index of the last segment that starts at or before ``t`` (-1 if none)."""
        return int(np.searchsorted(self.seg_start, t, "right")) - 1

    def is_open(self, t: int) -> bool:
        i = self.segment_index(t)
        return i >= 0 and bool(t < self.seg_end[i])

    def is_trading_day(self, day: int) -> bool:
        k = int(np.searchsorted(self.session_day, day, "left"))
        return k < len(self.session_day) and int(self.session_day[k]) == day

    def walk(self, start_us: int, amount_us: int) -> int | None:
        """Epoch microseconds at which ``amount_us`` of trading time has passed after ``start_us``.

        Counting starts at ``start_us`` inside a segment, otherwise at the next segment start. Trading time
        that ends exactly with a segment yields the end of that segment. None if the result lies beyond
        this schedule.
        """
        t = start_us // _MICROS
        i = self.segment_index(t)
        if i >= 0 and t < self.seg_end[i]:
            position = (int(self.cum_before[i]) - int(self.seg_start[i])) * _MICROS + start_us
        elif i + 1 < len(self.seg_start):
            position = int(self.cum_before[i + 1]) * _MICROS
        else:
            return None
        target = position + amount_us
        j = int(np.searchsorted(self.cum_end, -(-target // _MICROS), "left"))
        if j >= len(self.seg_end):
            return None
        return int(self.seg_end[j]) * _MICROS - (int(self.cum_end[j]) * _MICROS - target)


def _extended_windows(
    extended: ExtendedHours | None,
    zone: ZoneInfo,
    session_day: np.ndarray,
    session_open: np.ndarray,
    session_close: np.ndarray,
    session_early: np.ndarray,
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """Pre-market [pre_start, open) and after-hours [close, post_end) windows of every session."""
    rows: list[tuple[int, int, int]] = []
    if extended is not None:
        for day, open_, close, early in zip(
            session_day.tolist(), session_open.tolist(), session_close.tolist(), session_early.tolist(), strict=True
        ):
            pre_start = _local_ts(day, extended.pre_start, zone)
            post_end = _local_ts(day, extended.post_end_after_early_close if early else extended.post_end, zone)
            if pre_start < open_:
                rows.append((pre_start, open_, 0))
            if close < post_end:
                rows.append((close, post_end, 1))
    table = np.asarray(rows, dtype=np.int64).reshape(-1, 3)
    return table[:, 0], table[:, 1], table[:, 2].astype(bool)


# ------------------------------------------------------------------------------------------------
# Segment sources
# ------------------------------------------------------------------------------------------------
def _library_segments(
    code: str, first_day: int, last_day: int, lower: int | None, upper: int | None
) -> tuple[_Segments, np.ndarray]:
    """Regular segments and early-close days of exchange_calendars' calendar ``code`` for the given days.

    ``lower`` / ``upper`` (epoch days, None: unbounded) are the calendar's data range; the request is
    widened to at least ``_LIBRARY_MIN_SPAN_DAYS`` but never beyond that range. Raises whatever
    exchange_calendars raises (for example a ValueError for dates beyond its data).
    """
    request_first = min(first_day, last_day - _LIBRARY_MIN_SPAN_DAYS)
    request_last = max(last_day, first_day + _LIBRARY_MIN_SPAN_DAYS)
    if lower is not None:
        request_first = max(request_first, lower)
    if upper is not None:
        request_last = min(request_last, upper)
    with _LIBRARY_LOCK, warnings.catch_warnings():
        # exchange_calendars 4.13.3 emits pandas-4 / numpy deprecation warnings on pandas 3.1 (harmless).
        warnings.simplefilter("ignore", DeprecationWarning)
        calendar = xcals.get_calendar(
            code, start=pd.Timestamp(_to_date(request_first)), end=pd.Timestamp(_to_date(request_last))
        )
        days = _epoch_days(calendar.sessions)
        opens = calendar.opens_nanos.copy()
        closes = calendar.closes_nanos.copy()
        break_starts = calendar.break_starts_nanos.copy()
        break_ends = calendar.break_ends_nanos.copy()
        early_days = _epoch_days(calendar.early_closes)
    # A lunch break splits the session; half days (e.g. Hong Kong's) have no break.
    has_break = (
        (break_starts != _NAT) & (break_ends != _NAT) & (opens < break_starts)
        & (break_starts < break_ends) & (break_ends < closes)
    )
    segments = _Segments(
        np.concatenate((days, days[has_break])),
        np.concatenate((opens, break_ends[has_break])) // _NANOS,
        np.concatenate((np.where(has_break, break_starts, closes), closes[has_break])) // _NANOS,
    )
    return segments.select((segments.day >= first_day) & (segments.day <= last_day)), early_days


def _weekday_segments(days: np.ndarray, hours: Sequence[tuple[time, time]], zone: ZoneInfo) -> _Segments:
    """Segments of the given trading days from the venue's regular local hours."""
    return _Segments.of(
        [(day, _local_ts(day, begin, zone), _local_ts(day, end, zone)) for day in days.tolist() for begin, end in hours]
    )


def _always_open_segments(first_day: int, last_day: int) -> _Segments:
    """One segment [00:00, 24:00) UTC per day."""
    days = np.arange(first_day, last_day + 1, dtype=np.int64)
    return _Segments(days, days * _DAY, (days + 1) * _DAY)


def _rule_intervals(rule: VenueRule, first_day: int, last_day: int) -> list[tuple[int, int]]:
    """Open intervals (epoch seconds) of FX ('fx_week') or CME Globex ('globex_week') around the given days."""
    zone = ZoneInfo(RULE_TIMEZONE)
    intervals: list[tuple[int, int]] = []
    for day in range(first_day - 7, last_day + 2):  # New York dates; one week back covers the running week
        weekday = _weekday(day)
        if rule == "fx_week" and weekday == _SUNDAY:
            intervals.append((_local_ts(day, FX_WEEK_OPEN, zone), _local_ts(day + 5, FX_WEEK_CLOSE, zone)))
        elif rule == "globex_week" and (weekday == _SUNDAY or weekday <= _THURSDAY):
            intervals.append((_local_ts(day, GLOBEX_DAILY_OPEN, zone), _local_ts(day + 1, GLOBEX_DAILY_CLOSE, zone)))
    return intervals


def _split_at_midnight(intervals: Iterable[tuple[int, int]], first_day: int, last_day: int) -> _Segments:
    """Split intervals at UTC midnight; each piece belongs to the UTC date it starts on."""
    rows: list[tuple[int, int, int]] = []
    for start, end in intervals:
        while start < end:
            day = start // _DAY
            piece_end = min(end, (day + 1) * _DAY)
            if first_day <= day <= last_day:
                rows.append((day, start, piece_end))
            start = piece_end
    return _Segments.of(rows)


def _window(current: _Schedule | None, t_lo: int, t_hi: int) -> tuple[int, int]:
    """Trading dates a schedule must span to answer queries in [t_lo, t_hi]: the current span, extended
    by the rolling window on the side(s) where it falls short."""
    wanted_first, wanted_last = t_lo // _DAY - HISTORY_DAYS, t_hi // _DAY + LOOKAHEAD_DAYS
    if current is None:
        return wanted_first, wanted_last
    first = current.first_day if current.first_day * _DAY + _MARGIN <= t_lo else min(current.first_day, wanted_first)
    last = current.last_day if t_hi <= (current.last_day + 1) * _DAY - _MARGIN else max(current.last_day, wanted_last)
    return first, last


# ------------------------------------------------------------------------------------------------
# The calendar
# ------------------------------------------------------------------------------------------------
class ExchangeCalendar:
    """``contracts.MarketCalendar`` for all venues in ``venues.VENUES`` (see the module docstring)."""

    def __init__(self) -> None:
        self._venues = VENUES
        self._zones = {key: ZoneInfo(venue.timezone) for key, venue in VENUES.items()}
        self._schedules: dict[str, _Schedule] = {}
        self._locks = {key: threading.Lock() for key in VENUES}
        self._warned: set[str] = set()

    # -- description ----------------------------------------------------------------------------
    def exchanges(self) -> list[str]:
        return list(self._venues)

    def display_name(self, exchange: str) -> str:
        return self._venue(exchange).name_de

    def timezone(self, exchange: str) -> str:
        return self._venue(exchange).timezone

    # -- sessions -------------------------------------------------------------------------------
    def state(self, exchange: str, at: datetime) -> SessionState:
        """Phase at ``at`` (open / break / pre / post / closed) with the boundaries of that phase.

        24/7 venues (CRYPTO, KRAKEN) are always open (no boundaries). Otherwise since/until bound the current phase, next_open is
        the next segment start strictly after ``at`` and next_close the end of the current (open) or of the
        next segment.
        """
        venue = self._venue(exchange)
        t = _seconds(at)
        if venue.rule == "always_open":
            return SessionState(
                exchange, "open", is_open=True, since=None, until=None, next_open=None, next_close=None,
                note=NOTE_ALWAYS_OPEN,
            )
        s = self._schedule(venue, t, t)
        i = s.segment_index(t)
        if i >= 0 and t < s.seg_end[i]:
            run_end = _utc(s.run_end[i])
            return SessionState(
                exchange, "open", is_open=True, since=_utc(s.run_start[i]), until=run_end,
                next_open=_utc_at(s.seg_start, int(s.run_next[i])), next_close=run_end,
                note=NOTE_EARLY_CLOSE if s.session_early[s.seg_session[i]] else NOTE_OPEN,
            )
        following = i + 1
        next_open = _utc_at(s.seg_start, following)
        next_close = _utc_at(s.run_end, following)
        if 0 <= i and following < len(s.seg_start) and s.seg_session[i] == s.seg_session[following]:
            return SessionState(
                exchange, "break", is_open=False, since=_utc(s.seg_end[i]), until=next_open,
                next_open=next_open, next_close=next_close,
                note=NOTE_PAUSE if venue.rule == "globex_week" else NOTE_LUNCH,
            )
        k = int(np.searchsorted(s.ext_start, t, "right")) - 1
        if k >= 0 and t < s.ext_end[k]:
            post = bool(s.ext_is_post[k])
            return SessionState(
                exchange, "post" if post else "pre", is_open=False, since=_utc(s.ext_start[k]),
                until=_utc(s.ext_end[k]), next_open=next_open, next_close=next_close,
                note=NOTE_POST if post else NOTE_PRE,
            )
        since = _utc_at(s.seg_end, i)
        if k >= 0 and (since is None or s.ext_end[k] > s.seg_end[i]):
            since = _utc(s.ext_end[k])
        until = next_open
        if k + 1 < len(s.ext_start) and (until is None or s.ext_start[k + 1] < s.seg_start[following]):
            until = _utc(s.ext_start[k + 1])
        return SessionState(
            exchange, "closed", is_open=False, since=since, until=until, next_open=next_open,
            next_close=next_close, note=self._closed_note(venue, s, at),
        )

    def is_open(self, exchange: str, at: datetime) -> bool:
        venue = self._venue(exchange)
        t = _seconds(at)
        return self._schedule(venue, t, t).is_open(t)

    def segments(
        self, exchange: str, start: datetime, end: datetime, *, extended: bool = False
    ) -> list[SessionSegment]:
        """Regular segments (plus pre/post windows with ``extended``) intersecting [start, end), clipped."""
        venue = self._venue(exchange)
        lo, hi = _seconds(start), _ceil_seconds(end)
        if start >= end:
            return []
        s = self._schedule(venue, lo, hi)
        start_utc, end_utc = start.astimezone(UTC), end.astimezone(UTC)
        windows = [(s.seg_start, s.seg_end, None)]
        if extended:
            windows.append((s.ext_start, s.ext_end, s.ext_is_post))
        clipped: list[SessionSegment] = []
        for starts, ends, is_post in windows:
            first = int(np.searchsorted(ends, lo, "right"))  # first window ending after `start`
            stop = int(np.searchsorted(starts, hi, "left"))  # first window starting at or after `end`
            for k in range(first, stop):
                kind = "regular" if is_post is None else ("post" if is_post[k] else "pre")
                clipped.append(
                    SessionSegment(exchange, max(_utc(starts[k]), start_utc), min(_utc(ends[k]), end_utc), kind)
                )
        clipped.sort(key=lambda segment: segment.start)
        return clipped

    def session_date(self, exchange: str, at: datetime) -> date:
        """Local calendar date of ``at`` at the venue (the UTC date for CRYPTO / KRAKEN / FX / CME)."""
        venue = self._venue(exchange)
        if at.tzinfo is None:
            raise ValueError(_NAIVE_ERROR)
        return at.astimezone(self._zones[venue.key]).date()

    def last_completed_session(self, exchange: str, at: datetime) -> date | None:
        """Newest trading date whose last regular segment ended at or before ``at``."""
        venue = self._venue(exchange)
        t = _seconds(at)
        s = self._schedule(venue, t, t)
        k = int(np.searchsorted(s.session_end, t, "right")) - 1
        return None if k < 0 else _to_date(s.session_day[k])

    def minutes_since_open(self, exchange: str, at: datetime) -> int | None:
        """Whole trading minutes since the first segment of the current trading date opened; None if not open."""
        position = self._session_position(exchange, at)
        return None if position is None else position[0] // (60 * _MICROS)

    def minutes_to_close(self, exchange: str, at: datetime) -> int | None:
        """Whole trading minutes until the last segment of the current trading date ends; None if not open."""
        position = self._session_position(exchange, at)
        return None if position is None else position[1] // (60 * _MICROS)

    def add_trading_minutes(self, exchange: str, start: datetime, minutes: int) -> datetime:
        """The instant at which ``minutes`` trading minutes have passed after ``start``.

        Outside a session counting begins at the next open; time outside regular segments does not count.
        Trading time that ends exactly with a segment yields the end of that segment; ``minutes == 0``
        returns ``start``. Raises ValueError for negative ``minutes``.
        """
        venue = self._venue(exchange)
        if minutes < 0:
            raise ValueError(f"minutes must not be negative, got {minutes}")
        start_us = _micros(start)
        if minutes == 0:
            return start.astimezone(UTC)
        t = start_us // _MICROS
        s = self._schedule(venue, t, t)
        reach = LOOKAHEAD_DAYS * _DAY
        while (result_us := s.walk(start_us, minutes * 60 * _MICROS)) is None:
            s = self._schedule(venue, t, (s.last_day + 1) * _DAY + reach)
            reach *= 2
        return _EPOCH + timedelta(microseconds=result_us)

    # -- internals ------------------------------------------------------------------------------
    def _venue(self, exchange: str) -> Venue:
        try:
            return self._venues[exchange]
        except KeyError:
            known = ", ".join(self._venues)
            raise KeyError(f"unknown exchange calendar key {exchange!r}; known keys: {known}") from None

    def _session_position(self, exchange: str, at: datetime) -> tuple[int, int] | None:
        """(elapsed, remaining) trading microseconds of the current trading date; None if not in a segment."""
        venue = self._venue(exchange)
        at_us = _micros(at)
        t = at_us // _MICROS
        s = self._schedule(venue, t, t)
        i = s.segment_index(t)
        if i < 0 or t >= s.seg_end[i]:
            return None
        session = int(s.seg_session[i])
        position = (int(s.cum_before[i]) - int(s.seg_start[i])) * _MICROS + at_us
        elapsed = position - int(s.cum_before[s.session_first[session]]) * _MICROS
        remaining = int(s.cum_end[s.session_last[session]]) * _MICROS - position
        return elapsed, remaining

    def _closed_note(self, venue: Venue, schedule: _Schedule, at: datetime) -> str:
        if venue.rule != "library":
            return NOTE_WEEKEND  # FX and CME close only for the weekend
        local_day = at.astimezone(self._zones[venue.key]).date()
        if local_day.weekday() >= _SATURDAY:
            return NOTE_WEEKEND
        return NOTE_CLOSED if schedule.is_trading_day(_epoch_day(local_day)) else NOTE_HOLIDAY

    def _schedule(self, venue: Venue, t_lo: int, t_hi: int) -> _Schedule:
        """A schedule of ``venue`` that answers queries in [t_lo, t_hi]; built or extended on demand."""
        schedule = self._schedules.get(venue.key)
        if schedule is not None and schedule.covers(t_lo, t_hi):
            return schedule
        with self._locks[venue.key]:
            schedule = self._schedules.get(venue.key)
            if schedule is None or not schedule.covers(t_lo, t_hi):
                schedule = self._build(venue, *_window(schedule, t_lo, t_hi))
                self._schedules[venue.key] = schedule
            return schedule

    def _build(self, venue: Venue, first_day: int, last_day: int) -> _Schedule:
        started = perf_counter()
        early_days = _NO_DAYS
        if venue.rule == "always_open":
            segments = _always_open_segments(first_day, last_day)
        elif venue.rule == "library":
            segments, early_days = self._exchange_segments(venue, first_day, last_day)
        else:
            segments = _split_at_midnight(_rule_intervals(venue.rule, first_day, last_day), first_day, last_day)
        schedule = _Schedule.assemble(segments, early_days, first_day, last_day, venue.extended, self._zones[venue.key])
        log.info(
            "trading calendar %s: %d sessions %s..%s built in %.0f ms",
            venue.key, len(schedule.session_day), _to_date(first_day), _to_date(last_day),
            (perf_counter() - started) * 1000,
        )
        return schedule

    def _exchange_segments(self, venue: Venue, first_day: int, last_day: int) -> tuple[_Segments, np.ndarray]:
        """Library sessions inside the library's data range, weekday estimates outside it, minus closures.

        If the library fails, the whole range is estimated (logged as a warning).
        """
        code = venue.library_code or venue.key
        lower = None if venue.library_from is None else _epoch_day(venue.library_from)
        upper = None if venue.library_until is None else _epoch_day(venue.library_until)
        library_first = first_day if lower is None else max(first_day, lower)
        library_last = last_day if upper is None else min(last_day, upper)
        parts: list[_Segments] = []
        early_days = _NO_DAYS
        estimated = [(first_day, last_day)]  # inclusive ranges of epoch days without library data
        if library_first <= library_last:
            try:
                library, early_days = _library_segments(code, library_first, library_last, lower, upper)
            except Exception as exc:  # the calendar must keep working without the library
                self._warn_once(
                    venue.key,
                    f"exchange_calendars failed for {code} ({exc!r}): sessions estimated from weekdays and regular hours",
                )
            else:
                parts.append(library)
                estimated = [(first_day, library_first - 1), (library_last + 1, last_day)]
        estimated = [(begin, end) for begin, end in estimated if begin <= end]
        researched = RESEARCHED_CLOSURES.get(venue.key, {})
        if estimated:
            days = np.concatenate([np.arange(begin, end + 1, dtype=np.int64) for begin, end in estimated])
            years = sorted(
                year for year in researched
                if any(_to_date(begin).year <= year <= _to_date(end).year for begin, end in estimated)
            )
            spans = ", ".join(f"{_to_date(begin)}..{_to_date(end)}" for begin, end in estimated)
            self._warn_once(
                venue.key,
                f"no exchange_calendars data for {spans}: sessions estimated from weekdays and regular hours "
                f"(researched closures for: {', '.join(map(str, years)) or 'none'})",
            )
            weekdays = days[_weekday(days) < _SATURDAY]
            parts.append(_weekday_segments(weekdays, venue.regular_hours, self._zones[venue.key]))
        closures = EXTRA_CLOSURES.get(venue.key, frozenset()).union(*researched.values())
        return _Segments.concat(parts).without_days(closures), early_days

    def _warn_once(self, key: str, message: str) -> None:
        """Log the first estimate / library problem of a venue as a warning, later ones at debug level."""
        if key in self._warned:
            log.debug("trading calendar %s: %s", key, message)
            return
        self._warned.add(key)
        log.warning("trading calendar %s: %s", key, message)
